const CUT_MARKER = "**End of the reviewer path.**";

/** Split a steering document at the zone cut. Returns null if the cut is missing. */
export function splitZones(text: string): { zoneA: string; zoneB: string } | null {
  const i = text.indexOf(CUT_MARKER);
  if (i < 0) return null;
  const after = text.indexOf("\n", i);
  return { zoneA: text.slice(0, after < 0 ? text.length : after), zoneB: text.slice(after < 0 ? text.length : after) };
}

